using System.Text.Json.Nodes;
using PowerShapeMcp;
internal static class CurveScaleStopCheck {
 internal static int Run(string input,string output){var rows=JsonNode.Parse(File.ReadAllText(input))!["rows"]!.AsArray();var row=rows.Single(v=>v!["fault"]!.GetValue<string>()=="control")!;string root=row["root"]!.GetValue<string>(),id=row["inspectionId"]!.GetValue<string>();var reply=SolidScaleProof.Raw(root,id,row["inspectionSha256"]!.GetValue<string>()).Value;var args=row["arguments"]!.AsObject();CurveScaleStopTools.ValidateReply(root,reply,args);int cases=1;
  foreach(var fault in new[]{"identity","controls_claim","authority","release","original_capture","phase1"}){var forged=reply.DeepClone().AsObject();string fresh=Guid.NewGuid().ToString("N");forged["bridgeRequestId"]=fresh;if(fault=="identity")forged["selectionObserved"]!["selectedEntityKeys"]![0]![0]=40;else if(fault=="controls_claim")forged["fullControlProofAvailable"]=true;else if(fault=="authority")forged["mutationAuthorityGranted"]=true;else if(fault=="release")forged["copyFenceReleased"]=true;else if(fault=="original_capture")forged["sourceBefore"]!["entities"]![0]!["name"]="Foreign";else File.WriteAllText(Path.Combine(root,"curvescalephases",row["executionId"]!.GetValue<string>(),"01.started.json"),"{}");File.WriteAllText(Path.Combine(root,"responses",fresh+".json"),forged.ToJsonString());bool rejected=false;try{CurveScaleStopTools.ValidateReply(root,forged,args);}catch(ReferenceRejected){rejected=true;}if(!rejected)throw new InvalidDataException("Forged stop inspection accepted: "+fault);cases++;}
  foreach(var bad in rows.Where(v=>v!["fault"]!.GetValue<string>()is "extra_phase" or "claim_tamper")){bool rejected=false;try{_=CurveScaleStopTools.Origin(bad!["root"]!.GetValue<string>(),bad["executionId"]!.GetValue<string>(),bad["executionSha256"]!.GetValue<string>());}catch(ReferenceRejected){rejected=true;}if(!rejected)throw new InvalidDataException("Invalid stop origin accepted");cases++;}
  Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);File.WriteAllText(output,new JsonObject{["state"]="passed",["cases"]=cases,["cadConnectionAttempted"]=false}.ToJsonString(new(){WriteIndented=true}));Console.WriteLine($"PASS: {cases} actual Framework/SDK selection-stop proofs and forged control/authority/phase rejection; no CAD.");return 0;
 }
}
